<?php include '../includes/public_header.php'; ?><?php include '../includes/public_navbar.php'; ?><div class="layout"><?php include '../includes/public_sidebar.php'; ?><main class="public-content learning-public-page"><a class="learning-back-link" href="curso.php?asignacion=<?php echo $idAsignacion; ?>">← Volver al curso</a><section class="page-hero-compact learning-exam-header"><span class="section-kicker">Evaluación final</span><h1><?php echo learningH($eval['titulo']); ?></h1><p><?php echo learningH($eval['descripcion']); ?></p><div class="learning-course-hero-meta"><span>Nota mínima <?php echo round((float)$eval['nota_minima']); ?>%</span><span>Intentos <?php echo count($intentos); ?>/<?php echo (int)$eval['intentos_permitidos']; ?></span><span><?php echo count($preguntas); ?> preguntas</span></div></section>
