><span><?php echo str_pad((string)($idx+1),2,'0',STR_PAD_LEFT); ?></span><h3><?php echo learningH($p['pregunta']); ?></h3><small><?php echo learningH($p['puntos']); ?> pts</small></div><div class="learning-answer-list"><?php foreach($p['opciones'] as $o): ?><label><input type="radio" name="respuesta[<?php echo (int)$p['id_pregunta']; ?>]" value="<?php echo (int)$o['id_opcion']; ?>" required><span><?php echo learningH($o['texto']); ?></span></label><?php endforeach; ?></div></article><?php endforeach; ?><div class="learning-exam-submit"><p>Revisa tus respuestas antes de enviar.</p><button class="btn-primary-modern" type="submit">Finalizar evaluación</button></div></form><?php endif; ?>
